  Abbreviation LPREx := (LPRE H ra tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 spz sk0 LB0 LF obj bl bc key ents lo B shi m0 mo0).
  Abbreviation QIx := (QI H ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 spz sk0 LB0 LF obj bl bc key ents lo B shi m0 mo0).

  Definition NPRE (s : as_St H) (mo : Model) (m : mem) (errv : word) (LB LBm : list block) : Prop :=
    as_MPRES H mo0 mo
    /\ FRAME ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 spz obj m /\ spz mod 16 = 0 /\ 2 ^ 45 <= spf spz /\ spz <= 2 ^ 47
    /\ bv_unsigned ra mod 2 = 0
    /\ mem_inv asegs m /\ stk asegs m lo spz /\ rw_cells asegs m (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m B
    /\ tp = Z_to_bv 64 ATP /\ aceil <= lo /\ lo <= spz - AEMP_STACK /\ spz <= shi /\ spz <= B /\ B < 2 ^ 64
    /\ map_live_frame LF obj /\ obj + 40 <= aceil
    /\ umapx MI_A 24 (nval24 ASEGS) (lbl LB) m obj bl bc ents /\ umap_sh m 24 (bl, bc, ents)
    /\ bc <> BSEQ_LAST /\ Zlength ents + 1 < 2 ^ 24 /\ 0 <= key < 2 ^ 32
    /\ addressable m obj 40 /\ wr_at asegs m obj 40
    /\ (forall b, In b LB -> obj + 40 <= blk_addr b \/ blk_addr b + blk_size b <= obj)
    /\ fldA m tupp 8 keyp2 /\ accessible m tupp 8 /\ emp_src H LB0 spz obj tupp 8 /\ tupp mod 8 = 0
    /\ fldA m keyp2 4 key /\ accessible m keyp2 4 /\ emp_src H LB0 spz obj keyp2 4 /\ keyp2 mod 4 = 0
    /\ as_RHEAP H s LB m /\ Permutation LB (LB0 ++ LBm) /\ Permutation (lbl LBm) (umap_blocks 24 bl bc ents)
    /\ lb_own LBm m
    /\ xpres H LB0 spz [(obj, obj + 40)] m0 m
    /\ as_RFS H LF m /\ ACONST m /\ stack0 m lo shi
    /\ as_AL H s >= as_AL H sk0 /\ 0 <= as_AL H s
    /\ lb_small LB + 24 + nsmall (8 * bseq_next bc) <= RT_SMALL_MAX /\ Z.of_nat (length LB) + 2 <= RT_CNT_MAX
    /\ nlarge LB + nlg (8 * bseq_next bc) <= RT_LARGE_MAX /\ ((bc = 0 \/ Zlength ents = bc) -> ICM (8 * bseq_next bc) <= as_AL H s)
    /\ trace_ok (as_TR H) APC0_FREE [emp_del_ra EMP_U32].

  Lemma stage_node : forall (s : as_St H) (msF : machine_state) (mo : Model) (m : mem) (F : bvmap 5 word) (fc : bv 32)
      (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y19 y21 y25 y26 y27 y28 y29 y30 y31 : word) (errv : word) (LB LBm : list block),
    as_VIS H s msF = MS (mkR y1 (Z_to_bv 64 (spf spz)) gp tp y5 y6 y7 (Z_to_bv 64 obj) (Z_to_bv 64 (obj + 8)) y10 y11 y12 y13 y14
                             y15 y16 y17 (Z_to_bv 64 tupp) y19 (Z_to_bv 64 SHBASE) y21 (Z_to_bv 64 key) (Z_to_bv 64 (obj / 8))
                             (Z_to_bv 64 bc) y25 y26 y27 y28 y29 y30 y31)
                        F (Z_to_bv 64 E_NF) fc None m (seg_rom asegs) ->
    frm_zero fc -> as_AKREL H s (mkCfg msF mo) -> NPRE s mo m errv LB LBm ->
    (bc <> 0 -> y27 = Z_to_bv 64 (hmod key bc)) ->
    as_SR H QIx (mkCfg msF mo).
Proof.
